import java.util.*;
public class TwinPeaksDetailTest{public static void main(String[]args){var g=new TerrainGraph();var base=g.add(TerrainGraph.Type.CONSTANT,0,0);var cap=g.add(TerrainGraph.Type.CLAMP,0,0);cap.input[0]=base.id;cap.values.put("max",500.0);var output=g.add(TerrainGraph.Type.OUTPUT,0,0);output.input[0]=cap.id;LargeWorldBuilder.ACTIVE_GRAPH=g;if(LargeWorldBuilder.terrainCeiling()!=500)throw new AssertionError("Ceiling lost");int n=128;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,221));var rocks=g.add(TerrainGraph.Type.ROCKS,0,0);rocks.values.put("minY",220.0);rocks.values.put("maxY",500.0);rocks.values.put("stoneTransition",100.0);rocks.values.put("stoneSlope",0.0);rocks.values.put("stoneCoverage",1.0);rocks.values.put("density",0.0);var lower=RockNodes.apply(rocks,e,null,n,n,62,2024,()->false);Arrays.fill(e.height,350);var upper=RockNodes.apply(rocks,e,null,n,n,62,2024,()->false);int l=0,u=0;for(int i=0;i<n*n;i++){if(lower.material[i]==3)l++;if(upper.material[i]==3)u++;}if(l>100||u<n*n*.9)throw new AssertionError("No grass-to-stone transition");var w=new TerraForge.World(16,62,2024);Arrays.fill(w.height,400);w.environment.material=new byte[256];Arrays.fill(w.environment.material,(byte)3);w.environment.snow=new float[256];w.environment.snow[0]=.1f;w.environment.snow[1]=.9f;if(EnvironmentView.surfaceColor(w,0,0).getRed()>=EnvironmentView.surfaceColor(w,1,0).getRed())throw new AssertionError("No partial snow color");LargeWorldBuilder.ACTIVE_GRAPH=null;System.out.println("PASS: Y500 cap, gradual grass-to-stone coverage, partial-snow preview");}}
